function itemHit(e){const r=canvas.getBoundingClientRect(),rc=new THREE.Raycaster();rc.near=camera.near;rc.far=camera.far;rc.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);return rc.intersectObjects(meshes,false).find(h=>{let o=h.object;while(o){if(!o.visible)return false;o=o.parent;}return !!h.object.userData.id;});}
function describeItem(d){const info=itemDescriptions[d.id];if(!info)return `${d.id}\nModel geometry: ${d.dimensions||'Not separately dimensioned'}.\n${d.note||'Simplified component; confirm final technical details.'}\nSource: ${d.source||'Model interpretation; no separate PDF specification verified.'}`;const page=info.page;return `${info.title}\n\n${info.description}\n\nRevision comparison: ${info.version}\n${info.note?'\nTo confirm: '+info.note+'\n':''}\nSource: 79 Chemin Musie - Kitchen v.4.pdf — PDF p.${page}, sheet A.${String(page-1).padStart(2,'0')}.\nCurrent visual concept: ${state.conceptName}. Displayed finishes are exploratory and may differ from the PDF specifications.`;}
function removeOutline(){if(outline){scene.remove(outline);outline.geometry.dispose();outline.material.dispose();outline=null;}}
function selectionObjects(id){return meshes.filter(o=>o.userData.id===id||o.userData.componentId===id);}
function selectionDetail(id){const objects=selectionObjects(id),meta=objects[0]?.userData||{id};return {id,info:itemDescriptions[id]||null,description:describeItem({...meta,id}),meta:{...meta,id},config:getCabinetConfig(id)||getFeatureConfig(id)};}
function selectItem(id,notify=true){if(!itemDescriptions[id]&&!selectionObjects(id).length)return false;removeOutline();selected=id;root.updateMatrixWorld(true);const bounds=new THREE.Box3();for(const o of selectionObjects(id))bounds.expandByObject(o);if(!bounds.isEmpty()){outline=new THREE.Box3Helper(bounds,0xb97824);outline.material.depthTest=false;outline.material.transparent=true;outline.material.opacity=.85;outline.renderOrder=99;scene.add(outline);}if(notify)emit('selection',selectionDetail(id));render();return true;}
