let hoverFrame=0,lastHover=null;function updateHover(id){if(lastHover===id)return;lastHover=id;emit('hover',{id,title:id?(itemDescriptions[id]?.title||id):''});}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||e.buttons||pointers.size){updateHover(null);return;}cancelAnimationFrame(hoverFrame);hoverFrame=requestAnimationFrame(()=>{const hit=itemHit(e),id=hit?.object.userData.id||null;canvas.style.cursor=id?'pointer':'grab';updateHover(id);});});
