function syncUI(){for(const k of keys){const el=$(k);if(!el)continue;if(typeof state[k]==='boolean')el.checked=state[k];else el.value=state[k];}}
function applyState(partial){Object.assign(state,partial);state.cabinetOverrides=state.cabinetOverrides||{};state.featureOverrides=state.featureOverrides||{};syncUI();rebuild();}
function getCameraState(){return {view,target:orbit.target.toArray(),r:orbit.r,theta:orbit.theta,phi:orbit.phi,focusClip};}
function restoreCamera(s){if(!s||!Array.isArray(s.target)||s.target.length!==3||![...s.target,s.r,s.theta,s.phi].every(Number.isFinite))return false;view=['overview','sink','range','peninsula','plan','free','focus'].includes(s.view)?s.view:'free';focusClip=Number.isFinite(s.focusClip)?Math.max(15,Math.min(220,s.focusClip)):60;orbit.target.fromArray(s.target);orbit.r=Math.max(80,Math.min(650,s.r));orbit.theta=s.theta;orbit.phi=Math.max(.001,Math.min(1.65,s.phi));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));updateCamera();render();return true;}
function focusItem(id=selected){const bounds=new THREE.Box3();for(const o of selectionObjects(id))bounds.expandByObject(o);if(bounds.isEmpty())return false;if(id==='Floor footprint'||id==='Cabinet hardware'){setView(id==='Floor footprint'?'plan':'overview');return true;}freeOrbit();view='focus';bounds.getCenter(orbit.target);const size=bounds.getSize(new THREE.Vector3());orbit.r=Math.max(100,Math.min(380,Math.max(size.x,size.y,size.z)*2.4));focusClip=Math.min(220,size.length()/2+8);orbit.phi=1.3;const entry=cabinetIds.find(c=>c.id===id);const zone=entry?.zone||(['Custom hood cover','Range placeholder','Range backsplash'].includes(id)?'Range wall':['Peninsula bookcase','Range / peninsula countertops'].includes(id)?'Peninsula':'Sink wall');orbit.theta=zone==='Range wall'?Math.PI:zone==='Peninsula'?Math.PI/2:0;updateCamera();render();return true;}
function download(data,name,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('png').onclick=()=>{render();const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='Musie-'+view+'.png';a.click();};
function exportOBJ(){root.updateMatrixWorld(true);let out='# 79 Chemin Musie concept v1\n# Units: metres (source model inches)\n# No fabrication approval. See source and assumptions in HTML.\n',offset=1;const p=new THREE.Vector3();root.traverse(o=>{if(!o.isMesh||!o.visible)return;let a=o.parent;while(a){if(!a.visible)return;a=a.parent;}let geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry;const pos=geo.getAttribute('position');if(!pos)return;out+='o '+(o.userData.id||o.name||'part').replace(/[^a-z0-9_-]/gi,'_')+'\n';for(let i=0;i<pos.count;i++){p.fromBufferAttribute(pos,i).applyMatrix4(o.matrixWorld).multiplyScalar(.0254);out+=`v ${p.x.toFixed(5)} ${p.y.toFixed(5)} ${p.z.toFixed(5)}\n`;}for(let i=0;i+2<pos.count;i+=3)out+=`f ${offset+i} ${offset+i+1} ${offset+i+2}\n`;offset+=pos.count;if(geo!==o.geometry)geo.dispose();});return out;}
